from pathlib import Path
import csv,json,subprocess,time,os,hashlib,re
root=Path('/tmp/cosmictiger_step5');repo=Path('/home/dmarce1/workspace/cosmictiger')
base=['--run.test=pmmm','--run.darkMatterParticleCount=512','--run.gasParticleCount=0','--gravity.meshSize=8','--hydro.enabled=false','--gravity.cuda=false','--drift.cuda=false','--run.timeIntegrator=traditional','--hpx:threads=2','--hpx:bind=none']
data={'cpu_affinities':sorted(os.sched_getaffinity(0)),'case_options':base,'runs':[],'sha256':{n:hashlib.sha256((root/f'profile_{n}').read_bytes()).hexdigest() for n in ('source_only','double','float')}}
for trial,names in enumerate((('source_only','double','float'),('double','float','source_only'),('float','source_only','double'))):
 for name in names:
  work=root/f'profile_active_{name}_{trial}';work.mkdir(exist_ok=True)
  args=['/usr/bin/time','-f','%M','-o',str(work/'maxrss.txt'),str(root/f'profile_{name}'),*base]
  start=time.monotonic()
  with (work/'run.log').open('w') as log:subprocess.run(args,cwd=work,stdout=log,stderr=subprocess.STDOUT,timeout=240,check=True)
  rows=[json.loads(l[len('PMMM_PROFILE '):]) for l in (work/'run.log').read_text().splitlines() if l.startswith('PMMM_PROFILE ')]
  assert len(rows)==96
  apex={}
  with (work/'apex_profiles.csv').open() as f:
   for row in csv.DictReader(f):
    if row['name'].startswith('gravity.pmmm.'):
     apex[row['name']]={k:row[k] for k in ('num samples/calls','total','inclusive (ns)')}
  data['runs'].append({'name':name,'trial':trial,'wall_seconds':time.monotonic()-start,'maxrss_kib':int((work/'maxrss.txt').read_text()),'rows':rows,'apex':apex})
  (root/'profile_sweep.json').write_text(json.dumps(data,indent=2)+'\n')
  print(trial,name,round(data['runs'][-1]['wall_seconds'],3),len(rows),flush=True)

