from pathlib import Path
import csv,json,os,subprocess,time,hashlib,re
root=Path('/tmp/cosmictiger_step5');repo=Path('/home/dmarce1/workspace/cosmictiger')
options=json.loads((repo/'docs/fmm_root_deposition_benchmark.json').read_text())['options']
binaries={'source_only':Path('/tmp/cosmictiger_far_locals_validation/part3_cosmictiger'),'double':root/'part4_double_cosmictiger','float':repo/'build/pmmm_only_cpu/cosmictiger'}
data={'options':options,'cpu_affinities':sorted(os.sched_getaffinity(0)),'sha256':{k:hashlib.sha256(p.read_bytes()).hexdigest() for k,p in binaries.items()},'runs':[]}
for workload,size,mesh in [('dense',32768,16),('sparse',4096,32)]:
 for trial,names in enumerate((('source_only','double','float'),('double','float','source_only'),('float','source_only','double'))):
  for name in names:
   work=root/f'whole_{workload}_{name}_{trial}';work.mkdir(exist_ok=True)
   opts=dict(options,**{'run.darkMatterParticleCount':size,'gravity.meshSize':mesh,'output.directory':str(work/'simulation')})
   args=['/usr/bin/time','-f','%M','-o',str(work/'maxrss.txt'),str(binaries[name]),'--hpx:threads=2','--hpx:bind=none']+[f'--{k}={v}' for k,v in opts.items()]
   start=time.monotonic()
   with (work/'run.log').open('w') as log:subprocess.run(args,cwd=work,stdout=log,stderr=subprocess.STDOUT,timeout=240,check=True)
   phases={}
   for line in (work/'simulation/profile.txt').read_text().splitlines():
    m=re.fullmatch(r'(pmmmKick\.\S+)\s+(\d+)\s+(\d+):([0-5]\d):([0-5]\d\.\d+)\s+.*',line)
    if m:
     key,calls,h,mi,s=m.groups();phases[key]={'calls':int(calls),'seconds':int(h)*3600+int(mi)*60+float(s)}
   assert phases
   apex={}
   with (work/'apex_profiles.csv').open() as f:
    for row in csv.DictReader(f):
     if row['name'].startswith('gravity.pmmm.'):
      apex[row['name']]={k:row[k] for k in ('num samples/calls','total','inclusive (ns)')}
   data['runs'].append({'workload':workload,'name':name,'trial':trial,'particles':size,'mesh':mesh,'wall_seconds':time.monotonic()-start,'maxrss_kib':int((work/'maxrss.txt').read_text()),'phases':phases,'apex':apex})
   (root/'whole_solve.json').write_text(json.dumps(data,indent=2)+'\n')
   print(workload,trial,name,round(data['runs'][-1]['wall_seconds'],3),flush=True)
